/* @lc app=leetcode id=3395 lang=kotlin */ class Solution { fun c2(x: Long): Long = x * (x - 1) / 2 fun c(n: Long, k: Int): Long = if (k == 0) 1L else if (k == 1) n else c2(n) fun one(nums: IntArray, i: Int): Long = 1_000_000_007L.let { M -> nums[i].let { v -> nums.take(i).filter { it != v }.groupingBy { it }.eachCount().let { lm -> nums.drop(i + 1).filter { it != v }.groupingBy { it }.eachCount().let { rm -> nums.take(i).count { it == v }.toLong().let { cl -> nums.drop(i + 1).count { it == v }.toLong().let { cr -> (i - cl).let { lnv -> (nums.size - 1 - i - cr).let { rnv -> ((lnv * c2(rnv) - lnv * rm.values.sumOf { c2(it.toLong()) } - lm.entries.sumOf { (u, l) -> (rm[u] ?: 0).let { r -> l.toLong() * r * (rnv - r) } }) % M).let { g1 -> ((rnv * c2(lnv) - rnv * lm.values.sumOf { c2(it.toLong()) } - rm.entries.sumOf { (u, r) -> (lm[u] ?: 0).let { l -> r.toLong() * l * (lnv - l) } }) % M).let { g2 -> ((0..2).sumOf { a -> (0..2).filter { b -> a + b >= 2 }.sumOf { b -> c(cl, a) % M * (c(lnv, 2 - a) % M) % M * (c(cr, b) % M) % M * (c(rnv, 2 - b) % M) % M } } + cl % M * g1 + cr % M * g2) % M } } } } } } } } } } fun subsequencesWithMiddleMode(nums: IntArray): Int = nums.indices.fold(0L) { acc, i -> (acc + one(nums, i)) % 1_000_000_007L }.toInt() }